async function surgicalCards(t,width=390){const out=await fixture(t,width,true),{p,api}=out,c=await api('/cases','POST',{requestKey:'surgery3-case-001',kind:'surgery',species:'dog',weight:5,quickPatient:{name:'합성 수술 흐름'}});await practiceTab(p,'surgery');await p.locator('[data-cl-action=refresh]').click();await wardSettled(p);await p.locator('[data-cl-case="'+c.id+'"]').click();await p.locator('[data-cl-action=surgery-view][data-id=pre]').click();return {...out,id:c.id};}
async function checkSaved(p,key,value='true'){await p.waitForFunction(([k,v])=>document.querySelector('[data-cl-action=surgery-check-toggle][data-id="'+k+'"]')?.getAttribute('aria-pressed')===v&&!document.querySelector('.cl-workspace').inert,[key,value]);}
for(const width of [390,1440])test('surgery3: direct checks preserve exceptions notes and performer; cards browse without recording '+width,async t=>{
 const {p,api,id,errors}=await surgicalCards(t,width);const data={assessment:'unknown',consent:'notApplicable',equipment:'confirmed',airway:'unknown',monitoring:'unknown',recovery:'unknown',note:'보존할 합성 계획'};await api('/cases/'+id+'/events','POST',{revision:1,requestKey:'surgery3-initial-001',kind:'surgery.checks',data});await p.locator('[data-cl-action=refresh]').click();await wardSettled(p);await (await show(p,'[name=currentPerformer]')).selectOption('staff');const b=p.locator('[data-cl-action=surgery-check-toggle][data-id=assessment]');await b.click();await checkSaved(p,'assessment');assert.equal(await p.locator('.cl-dialog').count(),0);let r=await api('/cases/'+id);assert.equal(r.item.body.surgeryChecks.note,data.note);assert.equal(r.item.body.surgeryChecks.consent,'notApplicable');assert.equal(r.item.body.surgeryChecks.equipment,'confirmed');assert.equal(r.item.body.surgeryChecks.recorder.id,'staff');assert.match(await p.locator('.cl-surgery-flow').innerText(),/확인 3\/6/);await b.click();await checkSaved(p,'assessment','false');assert.equal((await api('/cases/'+id)).item.body.surgeryChecks.assessment,'unknown');
 const rev=(await api('/cases/'+id)).item.revision;for(const stage of ['record','recovery','end','pre']){await p.locator('[data-cl-action=surgery-view][data-id='+stage+']').click();assert.equal(await p.locator('[data-cl-action=phase]').count(),0);assert.equal(await p.locator('[data-cl-action=surgery-view][aria-current=step]').getAttribute('data-id'),'pre');}assert.equal((await api('/cases/'+id)).item.revision,rev);assert.ok(await p.locator('.cl-workspace').evaluate(e=>e.scrollWidth<=e.clientWidth+1));await p.screenshot({path:path.resolve(root,'../surgery3-'+width+'.png'),fullPage:true});assert.deepEqual(errors,[]);
});
test('surgery3: lost response retries same request once and concurrent changes are not overwritten',async t=>{
 const {p,api,f,id,errors}=await surgicalCards(t);let lose=true;const sent=[];f.clinicalHandler=async(path,m,b)=>{if(m==='POST'&&b.kind==='surgery.checks')sent.push(structuredClone(b));const r=await f.extras(path,m,b);if(m==='POST'&&b.kind==='surgery.checks'&&lose){lose=false;throw Error('합성 응답 유실');}return r;};const b=p.locator('[data-cl-action=surgery-check-toggle][data-id=assessment]');await b.click();await p.waitForFunction(()=>document.querySelector('.cl-message')?.textContent.includes('응답 유실'));await b.click();await checkSaved(p,'assessment');assert.equal(sent[0].requestKey,sent[1].requestKey);assert.equal((await api('/cases/'+id)).events.filter(x=>x.kind==='surgery.checks').length,1);
 let r=(await api('/cases/'+id)).item;await api('/cases/'+id+'/events','POST',{revision:r.revision,requestKey:'surgery3-concurrent-001',kind:'surgery.checks',data:{assessment:'confirmed',consent:'notApplicable',equipment:'unknown',airway:'unknown',monitoring:'unknown',recovery:'unknown',note:'동료 계획'}});await p.locator('[data-cl-action=surgery-check-toggle][data-id=equipment]').click();await p.waitForFunction(()=>document.querySelector('.cl-message')?.textContent.includes('다른 직원'));assert.equal((await api('/cases/'+id)).item.body.surgeryChecks.equipment,'unknown');await p.locator('[data-cl-action=refresh]').click();await wardSettled(p);await p.locator('[data-cl-action=surgery-check-toggle][data-id=equipment]').click();await checkSaved(p,'equipment');r=(await api('/cases/'+id)).item;assert.equal(r.body.surgeryChecks.consent,'notApplicable');assert.equal(r.body.surgeryChecks.note,'동료 계획');assert.deepEqual(errors,[]);
});
test('surgery3: recovery and final closure have specific actions and closed checks are read only',async t=>{
 const {p,api,id,errors}=await surgicalCards(t);await api('/cases/'+id+'/events','POST',{revision:1,requestKey:'surgery3-measurement-001',kind:'anesthesia.entry',data:{type:'measurement',observedAt:new Date().toISOString(),values:{heartRate:100}}});await p.locator('[data-cl-action=refresh]').click();await wardSettled(p);assert.equal(await p.locator('.cl-surgery-flow [aria-current=step]').getAttribute('data-id'),'record');await p.locator('[data-cl-action=surgery-view][data-id=recovery]').click();await p.locator('[data-cl-action=surgery-recovery]').click();const d=p.locator('.cl-dialog');assert.equal(await d.locator('[name=phase]').count(),0);await d.locator('[name=note]').fill('합성 회복 관찰');await wardSave(p);assert.equal((await api('/cases/'+id)).item.body.phase,'recovery');assert.equal(await p.locator('.cl-surgery-flow [aria-current=step]').getAttribute('data-id'),'recovery');await p.locator('[data-cl-action=surgery-view][data-id=end]').click();await p.locator('[data-cl-action=surgery-close]').click();assert.equal(await d.locator('[name=phase]').count(),0);await d.locator('[name=note]').fill('합성 마감 인계');await d.locator('[name=confirm]').check();await wardSave(p);assert.equal((await api('/cases/'+id)).item.status,'closed');assert.equal(await p.locator('.cl-surgery-flow [aria-current=step]').getAttribute('data-id'),'end');await p.locator('[data-cl-action=surgery-view][data-id=pre]').click();assert.equal(await p.locator('[data-cl-action=surgery-check-toggle]:disabled').count(),6);assert.equal(await p.locator('[data-cl-action=surgery-checks]').count(),0);assert.deepEqual(errors,[]);
});
test('surgery3: saved check with failed refresh is not sent again; read-only rights block quick checks',async t=>{
 const {p,api,f,id,errors}=await surgicalCards(t);let saved=false;f.clinicalHandler=async(path,m,b)=>{if(saved&&m==='GET'&&path.endsWith('/cases/'+id))throw Error('합성 조회 실패');const r=await f.extras(path,m,b);if(m==='POST'&&b.kind==='surgery.checks')saved=true;return r;};await p.locator('[data-cl-action=surgery-check-toggle][data-id=airway]').click();await p.waitForFunction(()=>document.querySelector('.cl-save-status')?.textContent.includes('확인은 저장됐습니다'));assert.equal(await p.locator('[data-cl-action=surgery-check-toggle]:disabled').count(),6);assert.equal((await api('/cases/'+id)).events.length,1);f.clinicalHandler=async(path,m,b)=>{const r=await f.extras(path,m,b);if(m==='GET'&&path.endsWith('/cases/'+id))return {...r,canRecord:false,canManage:false};return r;};await p.locator('[data-cl-action=refresh]').click();await wardSettled(p);assert.equal(await p.locator('[data-cl-action=surgery-check-toggle]:disabled').count(),6);assert.equal(await p.locator('[data-cl-action=surgery-checks]').count(),0);assert.deepEqual(errors,[]);
});

async function practiceTab(p,target){const button=p.locator('.clinic-navigation [data-tab="'+target+'"]');if(await button.count()){const nav=p.locator('.clinic-navigation');if(!await nav.isVisible())await p.locator('[data-practice-menu]').click();const group=button.locator('xpath=ancestor::details[1]');if(!await group.evaluate(d=>d.open))await group.locator('summary').first().click();await button.click();}else await p.locator('[data-tab="'+target+'"]').click();}

async function clinicNav(p,selector){const nav=p.locator('.clinic-navigation');if(!await nav.isVisible())await p.locator('[data-practice-menu]').click();const b=nav.locator(selector),group=b.locator('xpath=ancestor::details[1]');if(await group.count()&&!await group.evaluate(x=>x.open))await group.locator('summary').first().click();await b.click();}
